SELECT li.tenant_id AS tenantId, t.tenant_code AS tenantCode, li.login_code AS id, u.user_nm AS name, li.profile_image AS profileImage, li.stamp_image AS signatureImage, li.stamp_image AS stampImage, li.password_hash AS password, NULL AS ihidNum, u.email_addr AS email, d.department_nm AS departmentName, u.level_id AS levelId, lvl.item_code AS levelCode, lvl.item_nm AS levelName, CASE WHEN sr.role_code = 'PLATFORM_ADMIN' THEN 'ADM' ELSE 'USR' END AS userSe, u.department_id AS orgnztId, u.user_id::text AS uniqId, u.department_id AS groupId, COALESCE(d.department_nm, u.department_id::text) AS groupCode, CASE WHEN sr.role_code = 'PLATFORM_ADMIN' THEN 'ROLE_ADMIN' WHEN sr.role_code = 'TENANT_ADMIN' THEN 'ROLE_TENANT_ADMIN' ELSE 'ROLE_USER' END AS groupNm, sr.role_code AS roleCode, sr.role_id AS roleId FROM tb_login_account li JOIN tb_user u ON u.login_id = li.login_id JOIN tb_tenant t ON t.tenant_id = li.tenant_id JOIN LATERAL ( SELECT r.role_code, r.use_at, lr.role_id FROM tb_login_account_role lr JOIN tb_role r ON r.role_id = lr.role_id WHERE lr.login_id = li.login_id AND r.tenant_id = li.tenant_id
AND r.role_code = #{roleCode}
ORDER BY CASE WHEN r.role_code = 'PLATFORM_ADMIN' THEN 1 WHEN r.role_code = 'TENANT_ADMIN' THEN 2 WHEN r.role_code = 'TENANT_USER' THEN 3 ELSE 4 END, lr.role_id DESC LIMIT 1 ) sr ON TRUE LEFT JOIN tb_department d ON d.department_id = u.department_id AND d.tenant_id = li.tenant_id LEFT JOIN tb_common_code_group lg ON lg.tenant_id = li.tenant_id AND lg.group_code = 'LEVEL' AND COALESCE(lg.use_at, 'Y') = 'Y' LEFT JOIN tb_common_code_item lvl ON lvl.common_code_item_id = u.level_id AND lvl.group_id = lg.common_code_group_id AND lvl.tenant_id = li.tenant_id AND COALESCE(lvl.use_at, 'Y') = 'Y' WHERE (li.login_code = #{id} OR u.email_addr = #{id}) AND li.password_hash = #{password}
AND li.tenant_id = CAST(#{tenantId} AS bigint)
AND li.tenant_id = ( SELECT tenant_id FROM tb_tenant WHERE tenant_code = #{tenantCode} LIMIT 1 )
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(u.use_at, 'Y') = 'Y' AND COALESCE(d.use_at, 'Y') = 'Y' AND COALESCE(t.use_at, 'Y') = 'Y' AND COALESCE(sr.use_at, 'Y') = 'Y'

mapper.update:
UPDATE employees
SET email = #{email}
WHERE id = #{loginCode}

WITH emp AS (
    UPDATE employees
    SET password_hash = #{password}
    WHERE id = #{loginCode}
    RETURNING id
)
UPDATE tb_login_account la
SET password_hash = #{password},
    password_changed_at = now(),
    updated_at = now()
FROM emp
WHERE la.login_code = emp.id
  AND la.tenant_id = #{tenantId}

UPDATE tb_login_account SET password_hash = #{password}, updated_at = now() WHERE login_code = #{id}
AND tenant_id = CAST(#{tenantId} AS bigint)
AND tenant_id = ( SELECT tenant_id FROM tb_tenant WHERE tenant_code = #{tenantCode} LIMIT 1 )

