SELECT la.login_code FROM tb_user u JOIN tb_login_account la ON la.login_id = u.login_id AND la.tenant_id = u.tenant_id WHERE u.user_id = #{userId}
AND u.tenant_id = #{tenantId}
LIMIT 1
